def test_no_leash():
    assert solution.prox_point(0.0, -1.0, 0.0) == -1.0

def test_halfway_at_mu_one():
    assert abs(solution.prox_point(0.0, -1.0, 1.0) + 0.5) < 1e-12

def test_strong_leash():
    assert abs(solution.prox_point(0.0, -1.0, 4.0) + 0.2) < 1e-12

def test_global_not_zero():
    assert abs(solution.prox_point(2.0, 0.0, 1.0) - 1.0) < 1e-12

def test_negative_mu_raises():
    try:
        solution.prox_point(0.0, -1.0, -0.5)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_stays_between():
    w = solution.prox_point(1.0, -3.0, 3.0)
    assert -3.0 < w < 1.0

def test_returns_float():
    assert isinstance(solution.prox_point(0, -1, 1), float)
